using namespace Qt::StringLiterals;

struct MouseAction {
    Q_GADGET
    QML_VALUE_TYPE(mouseAction)

public:
    Q_PROPERTY(QString actionName MEMBER actionName)
    QString actionName;

    Q_PROPERTY(int mouseButton MEMBER mouseButton)
    int mouseButton{Qt::LeftButton};

    Q_PROPERTY(int modifier MEMBER modifier)
    int modifier{Qt::NoModifier};

    Q_PROPERTY(bool isDoubleClick MEMBER isDoubleClick)
    bool isDoubleClick{false};
};

inline QDebug operator<<(QDebug debug, const MouseAction &ba)
{
    QDebugStateSaver saver(debug);
    // clang-format off
    debug.nospace() << "\nButtonAction {"
                    << "\n\tactionName: "    << ba.actionName
                    << "\n\tmouseButton: "   << ba.mouseButton
                    << "\n\tmodifier: "      << ba.modifier
                    << "\n\tisDoubleClick: " << ba.isDoubleClick
                    << "\n}";
    // clang-format on
    return debug;
}

class MouseActionsModel : public QAbstractListModel
{
    Q_OBJECT
    QML_ELEMENT

public:
    explicit MouseActionsModel(QObject *parent = nullptr);

    enum Roles {
        MouseActionRole,
        ActionName,
        Button,
        I18nButton,
        Modifier,
        I18nModifier,
        IsDoubleClick,
    };
    Q_ENUM(Roles)

    enum MouseButton {
        NoButton = Qt::MouseButton::NoButton,
        Left = Qt::MouseButton::LeftButton,
        Middle = Qt::MouseButton::MiddleButton,
        Right = Qt::MouseButton::RightButton,
        Forward = Qt::MouseButton::ForwardButton,
        Back = Qt::MouseButton::BackButton,
